actions.script:
def BD = { v -> (v ?: 0) as java.math.BigDecimal }
def half = { v -> BD(v).divide(new java.math.BigDecimal('2'), 2, java.math.RoundingMode.HALF_UP) }
def stateOf = { g -> (g && g.toString().length() >= 2) ? g.toString().substring(0,2) : null }
int y = Integer.parseInt(returnPeriod.substring(2)); int m = Integer.parseInt(returnPeriod.substring(0,2))
def fromD = java.sql.Date.valueOf(java.time.LocalDate.of(y, m, 1))
def toD = java.sql.Date.valueOf(java.time.LocalDate.of(y, m, 1).plusMonths(1))

def invoices = ec.entity.find('mantle.account.invoice.Invoice')
    .condition('toPartyId', organizationPartyId)
    .condition('invoiceTypeEnumId', 'in', ['InvoicePurchase','InvoicePurchaseReturn','InvoiceSales','InvoiceSalesReturn','InvoiceCreditMemo'])
    .condition('invoiceDate', '>=', new java.sql.Timestamp(fromD.time))
    .condition('invoiceDate', '<', new java.sql.Timestamp(toD.time))
    .condition('statusId','in',['InvoiceFinalized','InvoiceSent','InvoiceAcked','InvoicePmtRecvd','InvoiceWriteOff','InvoiceReceived','InvoiceApproved','InvoicePmtSent']).disableAuthz().list()

def tTaxable = BD(0), tIgst = BD(0), tCgst = BD(0), tSgst = BD(0), tCess = BD(0)
int matched = 0, unmatched = 0
def rows = []
def supState = null
def selfGstin = ec.entity.find('zenith.erp.india.IndiaGstin').condition('partyId', organizationPartyId).disableAuthz().one()
supState = selfGstin ? (selfGstin.stateCode ?: stateOf(selfGstin.gstin)) : null

invoices.each { inv ->
    def sign = (inv.invoiceTypeEnumId == 'InvoicePurchaseReturn') ? BD(-1) : BD(1)
    def tax = ec.service.sync().name('zenith.india.GstServices.get#ChargedInvoiceTax').parameters([invoiceId:inv.invoiceId]).call()
    if (ec.message.hasError()) return
    def taxable=tax.taxable, iCgst=tax.cgst, iSgst=tax.sgst, iIgst=tax.igst, iCess=tax.cess
    tTaxable += taxable*sign; tIgst += iIgst*sign; tCgst += iCgst*sign; tSgst += iSgst*sign; tCess += iCess*sign

    def m2b = ec.entity.find('zenith.erp.india.Gstr2bRecord')
        .condition('organizationPartyId',organizationPartyId).condition('returnPeriod',returnPeriod)
        .condition('supplierGstin', inv.supplierGstin)
        .condition('invoiceNumber', inv.vendorInvoiceNumber).disableAuthz().list()
    boolean isM = m2b.any { it.matchStatus == 'Matched' && it.matchedInvoiceId == inv.invoiceId }
    if (isM) matched++ else unmatched++
    rows.add([invoiceId: inv.invoiceId, vendorName: inv.fromPartyId, invoiceNumber: inv.vendorInvoiceNumber,
              invoiceDate: inv.invoiceDate, taxableValue: taxable*sign, igst: iIgst*sign, cgst: iCgst*sign, sgst: iSgst*sign,
              cess: iCess*sign, matched: isM])
}
totalInvoices = invoices.size()
totalTaxableValue = tTaxable; totalIgst = tIgst; totalCgst = tCgst; totalSgst = tSgst; totalCess = tCess
matchedCount = matched; unmatchedCount = unmatched; reportData = rows

def BD = { v -> (v ?: 0) as java.math.BigDecimal }
def half = { v -> BD(v).divide(new java.math.BigDecimal('2'), 2, java.math.RoundingMode.HALF_UP) }
def stateOf = { g -> (g && g.toString().length() >= 2) ? g.toString().substring(0,2) : null }
int y = Integer.parseInt(returnPeriod.substring(2)); int m = Integer.parseInt(returnPeriod.substring(0,2))
def fromTs = new java.sql.Timestamp(java.sql.Date.valueOf(java.time.LocalDate.of(y, m, 1)).time)
def toTs = new java.sql.Timestamp(java.sql.Date.valueOf(java.time.LocalDate.of(y, m, 1).plusMonths(1)).time)

def selfGstin = ec.entity.find('zenith.erp.india.IndiaGstin').condition('partyId', organizationPartyId).disableAuthz().one()
def supState = selfGstin ? (selfGstin.stateCode ?: stateOf(selfGstin.gstin)) : null

// Aggregate charged tax over a set of invoices; direction: 'out' uses buyerGstin state, 'in' uses supplierGstin state.
def agg = { typeList, orgField, counterpartyGstinField ->
    def res = [taxable: BD(0), cgst: BD(0), sgst: BD(0), igst: BD(0), cess:BD(0)]
    def list = ec.entity.find('mantle.account.invoice.Invoice')
        .condition(orgField, organizationPartyId)
        .condition('invoiceTypeEnumId', 'in', typeList)
        .condition('invoiceDate', '>=', fromTs).condition('invoiceDate', '<', toTs)
        .condition('statusId','in',['InvoiceFinalized','InvoiceSent','InvoiceAcked','InvoicePmtRecvd','InvoiceWriteOff','InvoiceReceived','InvoiceApproved','InvoicePmtSent']).disableAuthz().list()
    list.each { inv ->
        // Stored invoice eligibility is authoritative for inward credit only.
        // Do not use today's registration regime to rewrite historical eligibility.
        if (orgField == 'toPartyId' && (inv.itcEligible == 'N' || inv.isCompositionDealer == 'Y')) return
        boolean isReturn = inv.invoiceTypeEnumId in ['InvoiceSalesReturn','InvoicePurchaseReturn','InvoiceCreditMemo']
        def sign = isReturn ? BD(-1) : BD(1)
        def tax=ec.service.sync().name('zenith.india.GstServices.get#ChargedInvoiceTax').parameters([invoiceId:inv.invoiceId]).call()
        if (ec.message.hasError()) return
        res.taxable += tax.taxable*sign
        ['cgst','sgst','igst','cess'].each { res[it] += tax[it]*sign }
    }
    return res
}

// 3.1 outward = sales invoices (POS sales already create linked InvoiceSales, so no double count).
def out = agg(['InvoiceSales','InvoiceSalesReturn','InvoiceSalesDebit','InvoiceCreditMemo'], 'fromPartyId', 'buyerGstin')
// 4 ITC = purchase invoices.
def itc = agg(['InvoicePurchase','InvoicePurchaseReturn','InvoiceSales','InvoiceSalesReturn','InvoiceCreditMemo'], 'toPartyId', 'supplierGstin')

table31 = [taxableValue: out.taxable, igst: out.igst, cgst: out.cgst, sgst: out.sgst, cess: out.cess]
table32 = [igst: BD(0), cgst: BD(0), sgst: BD(0), cess: BD(0)]
table4 = [igst: itc.igst, cgst: itc.cgst, sgst: itc.sgst, cess: itc.cess]
table5 = [interState: BD(0), intraState: BD(0)]
netTaxPayable = [igst: out.igst - itc.igst, cgst: out.cgst - itc.cgst, sgst: out.sgst - itc.sgst, cess: out.cess-itc.cess]

matchedCount=0; unmatchedCount=0; missingInBooksCount=0
if (!gstr2bJsonFile || gstr2bJsonFile.size == 0 || gstr2bJsonFile.size > 5*1024*1024) {
    ec.message.addError('Upload a non-empty GSTR-2B JSON file of at most 5 MB.'); return
}
try {
    def payload=new groovy.json.JsonSlurper().parseText(new String(gstr2bJsonFile.get(),'UTF-8'))
    def data=payload.data ?: payload
    def cfg=ec.entity.find('zenith.erp.india.IndiaGstConfig').condition('organizationPartyId',organizationPartyId).one()
    if (!cfg?.gstin || data.gstin != cfg.gstin || (data.rtnprd ?: data.fp) != returnPeriod) throw new IllegalArgumentException('GSTIN and period must match the selected organization and return period.')
    def suppliers=data.docdata?.b2b ?: data.b2b
    if (!(suppliers instanceof List)) throw new IllegalArgumentException('B2B invoice data is missing.')
    def bd={ v -> (v == null ? 0 : v) as BigDecimal }
    for (supplier in suppliers) for (inv in (supplier.inv ?: [])) {
        def gstin=supplier.ctin ?: supplier.gstin, number=inv.inum
        if (!gstin || !number) throw new IllegalArgumentException('Supplier GSTIN and invoice number are required.')
        def sums=[taxableAmount:0G,igstAmount:0G,cgstAmount:0G,sgstAmount:0G,cessAmount:0G]
        for (item in (inv.items ?: inv.itms ?: [])) {
            def det=item.itm_det ?: item
            [taxableAmount:'txval',igstAmount:'iamt',cgstAmount:'camt',sgstAmount:'samt',cessAmount:'csamt'].each { k,v -> sums[k]+=bd(det[v]) }
        }
        def book=ec.entity.find('mantle.account.invoice.Invoice').condition('toPartyId',organizationPartyId)
            .condition('invoiceTypeEnumId','InvoicePurchase').condition('supplierGstin',gstin)
            .condition('vendorInvoiceNumber',number).condition('statusId','in',['InvoiceFinalized','InvoiceSent','InvoiceAcked','InvoicePmtRecvd','InvoiceWriteOff','InvoiceReceived','InvoiceApproved','InvoicePmtSent']).list()
        def reason=null, status='MissingInBooks', matchedId=null
        if (book.size()==1) {
            def tax=ec.service.sync().name('zenith.india.GstServices.get#ChargedInvoiceTax').parameters([invoiceId:book[0].invoiceId]).call()
            if(ec.message.hasError()) throw new IllegalArgumentException('Book invoice does not reconcile.')
            boolean matches=[taxableAmount:'taxable',igstAmount:'igst',cgstAmount:'cgst',sgstAmount:'sgst',cessAmount:'cess'].every { k,v -> (sums[k]-bd(tax[v])).abs() <= 0.01G }
            status=matches ? 'Matched' : 'Mismatch'; reason=matches ? null : 'Taxable value or tax components differ from books.'; matchedId=book[0].invoiceId
        } else if(book.size()>1) {status='Mismatch';reason='Multiple book invoices have this supplier and number.'}
        def existing=ec.entity.find('zenith.erp.india.Gstr2bRecord').condition('organizationPartyId',organizationPartyId)
            .condition('returnPeriod',returnPeriod).condition('supplierGstin',gstin).condition('invoiceNumber',number).one()
        def values=sums+[organizationPartyId:organizationPartyId,returnPeriod:returnPeriod,supplierGstin:gstin,invoiceNumber:number,totalAmount:bd(inv.val),matchStatus:status,matchedInvoiceId:matchedId,mismatchReasons:reason,matchDate:ec.user.nowTimestamp]
        if(existing) {existing.setAll(values);existing.update()}
        else ec.entity.makeValue('zenith.erp.india.Gstr2bRecord').setAll(values).setSequencedIdPrimary().create()
        if(status=='Matched') matchedCount++
        else if(status=='MissingInBooks') missingInBooksCount++
        else unmatchedCount++
    }
} catch(Exception ignored) {
    ec.transaction.setRollbackOnly('Invalid GSTR-2B input',null)
    ec.message.addError('GSTR-2B import failed validation. No records were saved. Check GSTIN, period and invoice data.')
    matchedCount=0; unmatchedCount=0; missingInBooksCount=0
}
